entries[24866] = { ["name"] = "Schnelligkeit der Wildnis", ["text"] = "Benötigt Katzengestalt\nErhöht Euer Bewegungstempo in Katzengestalt um 30% sowie Eure Ausweichchance um 4%, während Ihr Euch in Katzen- oder Bärengestalt befindet.\n\nZusätzlich besteht eine Chance von 100%, dass Eure Fähigkeiten 'Spurt' und 'Anstachelndes Brüllen' bei Nutzung bestehende bewegungseinschränkende Effekte von allen betroffenen Zielen entfernen." }
